#!/bin/sh
# Starts a private OpenSSH server for the ShellDrive interop tests (decisions.md D21: test
# infrastructure only). It runs as the calling WSL user, never as root, with its own sshd_config,
# host key and authorized_keys; the system sshd and /etc/ssh are not touched.
#
#   Windows:  powershell -File tests\fixtures\wsl-sshd\start.ps1      (or: wsl.exe -e sh <path>/start.sh)
#   WSL:      sh tests/fixtures/wsl-sshd/start.sh
#
# Environment: SD_SSHD_PORT (default 2222). Listens on 127.0.0.1 only (WSL2 forwards localhost).
# Server state (keys, config, log, pid) lives on the Linux file system, because sshd checks key
# permissions that /mnt/c cannot express; the client material the Windows tests need is copied to
# ./state/ (gitignored).
set -eu

PORT="${SD_SSHD_PORT:-2222}"
HERE="$(cd "$(dirname "$0")" && pwd)"
STATE_WIN="$HERE/state"
RUN="${XDG_STATE_HOME:-$HOME/.local/state}/shelldrive-wsl-sshd"
SSHD=/usr/sbin/sshd
USER_NAME="$(id -un)"
PASS="shelldrive-test-pass"

if [ ! -x "$SSHD" ]; then
  echo "sshd not found: install it with 'sudo apt install openssh-server' (the service can stay disabled)" >&2
  exit 1
fi

mkdir -p "$RUN" "$STATE_WIN"
chmod 700 "$RUN"

if [ -f "$RUN/sshd.pid" ] && kill -0 "$(cat "$RUN/sshd.pid")" 2>/dev/null; then
  echo "fixture sshd already running (pid $(cat "$RUN/sshd.pid"), port $(cat "$RUN/port" 2>/dev/null || echo "?"))"
  exit 0
fi

[ -f "$RUN/ssh_host_ed25519_key" ] || ssh-keygen -q -t ed25519 -N '' -C shelldrive-fixture-host -f "$RUN/ssh_host_ed25519_key"
[ -f "$RUN/client_ed25519" ] || ssh-keygen -q -t ed25519 -N '' -C shelldrive-test -f "$RUN/client_ed25519"
[ -f "$RUN/client_ed25519_enc" ] || ssh-keygen -q -t ed25519 -N "$PASS" -C shelldrive-test-enc -f "$RUN/client_ed25519_enc"
cat "$RUN/client_ed25519.pub" "$RUN/client_ed25519_enc.pub" > "$RUN/authorized_keys"
chmod 600 "$RUN/authorized_keys" "$RUN/ssh_host_ed25519_key" "$RUN/client_ed25519" "$RUN/client_ed25519_enc"

cat > "$RUN/sshd_config" <<CONF
# Generated by tests/fixtures/wsl-sshd/start.sh. Private test instance; not the system sshd.
Port $PORT
ListenAddress 127.0.0.1
HostKey $RUN/ssh_host_ed25519_key
PidFile $RUN/sshd.pid
AuthorizedKeysFile $RUN/authorized_keys
AllowUsers $USER_NAME
PermitRootLogin no
UsePAM no
PubkeyAuthentication yes
# A non-root sshd cannot read /etc/shadow: password and keyboard-interactive logins cannot succeed
# here. See README.md for manual password testing.
PasswordAuthentication no
KbdInteractiveAuthentication no
StrictModes no
MaxAuthTries 10
MaxSessions 10
# server-initiated rekeys during the bulk interop test
RekeyLimit 4M 1h
Subsystem sftp internal-sftp
LogLevel VERBOSE
CONF

"$SSHD" -t -f "$RUN/sshd_config"
"$SSHD" -f "$RUN/sshd_config" -E "$RUN/sshd.log"
echo "$PORT" > "$RUN/port"

# client material for the Windows tests
cp "$RUN/client_ed25519" "$RUN/client_ed25519_enc" "$STATE_WIN/"
{
  echo "user=$USER_NAME"
  echo "port=$PORT"
  echo "key=client_ed25519"
  echo "key_enc=client_ed25519_enc"
  echo "pass=$PASS"
  echo "hostkey=$(cut -d' ' -f1,2 "$RUN/ssh_host_ed25519_key.pub")"
} > "$STATE_WIN/env"

i=0
while [ $i -lt 50 ]; do
  [ -f "$RUN/sshd.pid" ] && break
  sleep 0.1
  i=$((i + 1))
done
echo "fixture sshd listening on 127.0.0.1:$PORT as $USER_NAME (pid $(cat "$RUN/sshd.pid" 2>/dev/null || echo "?"), log $RUN/sshd.log)"
